export class ThermostatStore {
 private adapter: ThermostatAdapter
 private state: string = ''
 async executeCommand(command: string): Promise<void> {
  await this.adapter.executeAction(command)
 }
 async reloadState(): Promise<void> {
  const current = await this.adapter.loadCurrent()
  this.state = current
 }
}
